#!/usr/bin/env python3
"""Convert block-format atoms into JSONL. usage: conv.py out.jsonl part1.txt part2.txt ..."""
import json, re, sys
from pathlib import Path
repo = Path("/home/user/guidebook")
STAGES = {"base","research","evidence","judgment","synthesis","specification","render","cross"}
def build(path):
    raw = (repo/path).read_text(encoding="utf-8", errors="replace")
    chars=[]; lines=[]
    for ln, line in enumerate(raw.split("\n"),1):
        s = re.sub(r"^\s*>\s?","",line)
        for ch in s+"\n":
            if ch.isspace():
                if chars and chars[-1] != " ":
                    chars.append(" "); lines.append(ln)
            else:
                chars.append(ch); lines.append(ln)
    return "".join(chars), lines
cache={}
norm = lambda s: re.sub(r"\s+"," ",s).strip()
out=[]; bad=0
cur=None; atom=None
def flush():
    global atom, bad
    if atom is None: return
    a=atom; atom=None
    q=norm(re.sub(r"^\s*>\s?","",a["Q"]))
    if len(q)>300: print(f"TOO LONG ({len(q)}): {q[:60]}"); bad+=1
    if cur not in cache: cache[cur]=build(cur)
    t,l=cache[cur]
    i=t.find(q)
    if i<0:
        print(f"QUOTE NOT FOUND in {cur}: {q[:100]!r}"); bad+=1; line=0
    else: line=l[i]
    st=[x.strip() for x in a.get("G","").split(",") if x.strip()]
    for x in st:
        if x not in STAGES: print(f"bad stage {x} in {q[:50]}"); bad+=1
    objs=[x.strip() for x in a.get("O","").split(";") if x.strip()]
    def nz(k):
        v=a.get(k,"").strip()
        return None if v in ("","-") else v
    mod,spk,date,sta=[x.strip() for x in a["H"].split("|")]
    out.append({"id":"TMP","source":f"{cur}:{line}","quote":q if False else a["Q"].strip(),"modality":mod,"subject":a["S"].strip(),
      "claim":a["C"].strip(),"scope":{"stages":st,"objects":objs},"speaker":spk,"date":None if date in("-","") else date,
      "status":sta,"status_evidence":nz("SE"),"superseded_by":nz("SB"),"enforcement":nz("EN"),"ambiguity":nz("AM")})
for pf in sys.argv[2:]:
    for raw in open(pf,encoding="utf-8"):
        raw=raw.rstrip("\n")
        if raw.startswith("==="):
            flush(); cur=raw[3:].strip(); continue
        if raw.startswith("@ "):
            flush(); atom={"H":raw[2:]}; continue
        m=re.match(r"^(Q|S|C|G|O|SE|SB|EN|AM):\s?(.*)$",raw)
        if m and atom is not None:
            atom[m.group(1)]=m.group(2); continue
        if raw.strip()=="" or raw.startswith("#"): continue
        print("UNPARSED:",raw[:80]); bad+=1
flush()
# renumber
for n,a in enumerate(out,1): a["id"]=f"DRS-{n:03d}"
with open(sys.argv[1],"w",encoding="utf-8") as f:
    for a in out: f.write(json.dumps(a,ensure_ascii=False)+"\n")
print(len(out),"atoms;",bad,"conversion problems")
EOF
echo ok

